package com.kafka.backend.money;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;
import java.math.BigDecimal;import java.time.*;import java.util.*;
import static org.assertj.core.api.Assertions.*;
/** Exact count-only/legacy row-filter equivalence in a disposable loopback schema. */
@EnabledIfEnvironmentVariable(named="DEV_DB_URL",matches="jdbc:postgresql://127\\.0\\.0\\.1:55467/postgres.*")
class MoneyWorkbenchSummaryPostgresTest {
 final MoneyRecommendationDraftReadPostgresTest f=new MoneyRecommendationDraftReadPostgresTest();
 @BeforeEach void setup()throws Exception{f.setup();}@AfterEach void cleanup(){f.cleanup();}
 MoneyRecommendationService.Filters filters(){return f.f.filters();}
 MoneyRecommendationService.Filters filter(String kind,String search,boolean excluded,String accounts,String categories,BigDecimal min,BigDecimal max,String origin){return new MoneyRecommendationService.Filters("2026-09-01","2026-09-30",kind,search,excluded,accounts,categories,min,max,"IGNORED_BY_SUMMARY",origin);}
 Map<String,Object> legacy(MoneyRecommendationService.Filters p){var result=new LinkedHashMap<String,Object>();for(String state:List.of("ALL","UNCLASSIFIED","READY","ERRORS"))result.put(state,f.f.web.bookkeeping(p.from(),p.to(),p.kind(),p.search(),1,0,p.includeExcluded(),p.accountIds(),p.categoryIds(),p.minAmount(),p.maxAmount(),state,p.classificationOrigin()).get("total"));return result;}
 Map<String,Object> equivalent(MoneyRecommendationService.Filters p){var expected=legacy(p);f.queries.set(0);var actual=f.read.execute(status->f.service.summary(p));assertThat(actual).isEqualTo(expected);assertThat(actual.keySet()).containsExactly("ALL","UNCLASSIFIED","READY","ERRORS");actual.values().forEach(v->assertThat(v).isInstanceOf(Long.class));assertThat(f.queries).hasValue(1);assertThat(f.f.calls).hasValue(0);return actual;}
 void counts(Map<String,Object> r,long all,long unclassified,long ready,long errors){assertThat(r).containsEntry("ALL",all).containsEntry("UNCLASSIFIED",unclassified).containsEntry("READY",ready).containsEntry("ERRORS",errors);}
 void override(UUID id,Map<String,Object> values){f.db.update("insert into money_bookkeeping_overrides(id,user_id,transaction_id,slot,version,overrides) values(?,?,?,0,1,cast(? as jsonb))",UUID.randomUUID(),f.f.owner,id,f.f.json.writeValueAsString(values));}
 UUID account(){return f.f.money.createAccount(new MoneyTypes.AccountInput("IBK","Synthetic other",MoneyTypes.AccountRole.SPENDING,null,null)).id();}
 @Test void emptyReturnsFourLongZeroesWithOneQuery(){f.seed(0);counts(equivalent(filters()),0,0,0,0);}
 @ParameterizedTest @ValueSource(strings={"expense","income","classified","archivedCategory","archivedParent","excluded","overrideExcluded","includeOverrideExcluded","merged","untracked","archivedAccount","inactiveAccount","invalidEffectiveAccount","financialReview","usd","mixedCurrencies","refund","transfer","dateIntoPeriod","dateOutOfPeriod","lowerBoundary","upperBoundary","upperExclusive","savedClassification","loanInterest","loanPrincipalOnly","loanUnresolved"}) void membershipAndFinancialBoundariesMatchLegacy(String scenario){
  UUID parent=null;if(scenario.equals("archivedParent")){parent=f.f.product.saveCategory(null,new MoneyProductService.CategoryInput("Parent","#123456",false,null,"EXPENSE",null,0)).id();f.f.category=f.f.product.saveCategory(null,new MoneyProductService.CategoryInput("Child","#123456",false,null,"EXPENSE",null,0,parent,false)).id();}
  f.seed(1);UUID id=f.transactions.getFirst();var p=filters();long all=1,unc=1,ready=1;
  switch(scenario){
   case "income"->{f.db.update("update money_transactions set type='INCOME',from_account_id=null,to_account_id=? where id=?",f.f.account,id);f.db.update("insert into money_tracking_accounts(user_id,kind,slot,account_id) values(?,'INCOME',1,?)",f.f.owner,f.f.account);p=filter("INCOME",null,false,null,null,null,null,null);}
   case "classified","archivedCategory","archivedParent"->{f.db.update("update money_transactions set category_id=? where id=?",f.f.category,id);unc=0;if(scenario.equals("archivedCategory"))f.db.update("update money_categories set archived=true where id=?",f.f.category);if(parent!=null)f.db.update("update money_categories set archived=true where id=?",parent);}
   case "excluded"->{f.db.update("update money_transactions set excluded=true where id=?",id);p=filter("EXPENSE","",true,null,null,null,null,null);all=unc=ready=0;}
   case "overrideExcluded","includeOverrideExcluded"->{override(id,Map.of("excluded",true));if(scenario.equals("includeOverrideExcluded"))p=filter("EXPENSE","",true,null,null,null,null,null);else all=unc=ready=0;}
   case "merged"->{UUID into=f.f.expense("Merge target");f.db.update("update money_transactions set merged_into=? where id=?",into,id);ready=0;}
   case "untracked"->{f.db.update("update money_transactions set from_account_id=? where id=?",account(),id);all=unc=ready=0;}
   case "archivedAccount"->{f.db.update("update money_accounts set archived=true where id=?",f.f.account);all=unc=ready=0;}
   case "inactiveAccount"->{f.db.update("update money_accounts set include_in_statistics=false where id=?",f.f.account);all=unc=ready=0;}
   case "invalidEffectiveAccount"->override(id,Map.of("accountId",UUID.randomUUID()));
   case "financialReview"->f.f.product.save(null,new MoneyProductService.Entry(MoneyTypes.TransactionType.INCOME,null,account(),new BigDecimal("1000"),Instant.parse("2026-09-15T01:00:00Z"),"합성 카페",null,null,false,null,null,"Opposing evidence"));
   case "usd"->f.db.update("update money_transactions set currency='USD' where id=?",id);
   case "mixedCurrencies"->{f.f.expense("KRW second");f.db.update("update money_transactions set currency='USD' where id=?",id);all=unc=2;}
   case "refund"->{f.f.product.save(null,new MoneyProductService.Entry(MoneyTypes.TransactionType.REFUND,null,account(),new BigDecimal("100"),Instant.parse("2026-09-15T01:00:00Z"),null,null,null,false,id,null,"Refund"));all=unc=2;}
   case "transfer"->f.f.product.save(null,new MoneyProductService.Entry(MoneyTypes.TransactionType.TRANSFER,f.f.account,account(),new BigDecimal("100"),Instant.parse("2026-09-15T01:00:00Z"),null,null,null,false,null,null,"Transfer"));
   case "dateIntoPeriod"->{f.db.update("update money_transactions set occurred_at='2026-08-01T00:00:00Z' where id=?",id);override(id,Map.of("occurredAt","2026-09-15T01:00:00Z"));}
   case "dateOutOfPeriod"->{override(id,Map.of("occurredAt","2026-10-01T00:00:00Z"));all=unc=ready=0;}
   case "lowerBoundary"->override(id,Map.of("occurredAt","2026-08-31T15:00:00Z"));
   case "upperBoundary"->override(id,Map.of("occurredAt","2026-09-30T14:59:59.999999Z"));
   case "upperExclusive"->{override(id,Map.of("occurredAt","2026-09-30T15:00:00Z"));all=unc=ready=0;}
   case "savedClassification"->{var item=f.f.saveItem(id,f.f.category);var result=f.f.service.save(new MoneyRecommendationService.Save(UUID.randomUUID(),List.of(item)));assertThat(f.f.savedItem(result,id)).containsEntry("status","SAVED");unc=ready=0;}
   case "loanInterest","loanPrincipalOnly","loanUnresolved"->{var input=new MoneyWebTypes.LoanInput("Synthetic loan","Synthetic lender","PERSONAL",new BigDecimal("1000"),new BigDecimal("1000"),new BigDecimal("4.5"),BigDecimal.ZERO,25,LocalDate.of(2026,10,25),f.f.account,LocalDate.of(2026,1,1),LocalDate.of(2028,1,1),"ACTIVE",null,0L);var loan=f.f.web.saveLoan(null,input);var financial=new MoneyFinancialService(f.db,()->f.f.owner,f.f.money,f.f.product,f.f.web,f.f.json);boolean unresolved=scenario.equals("loanUnresolved"),interest=scenario.equals("loanInterest");financial.payment(null,new MoneyFinancialService.PaymentInput(loan.id(),f.f.account,new BigDecimal(interest?"120":"100"),unresolved?null:new BigDecimal("100"),unresolved?null:new BigDecimal(interest?"15":"0"),unresolved?null:new BigDecimal(interest?"5":"0"),Instant.parse("2026-09-15T01:00:00Z"),"Loan",null,loan.version()));if(interest)all=unc=2;}
  }
  counts(equivalent(p),all,unc,ready,0);
 }
 @ParameterizedTest @ValueSource(strings={"FAILED_KNOWN","STALE_CONFLICT","EXTERNAL_OUTCOME_UNKNOWN","RUNNING","QUEUED","BUDGET_WAIT"}) void recommendationIssuesOverlapUnclassifiedAndReady(String status){f.seed(1);f.db.update("update money_recommendation_items set status=?",status);counts(equivalent(filters()),1,1,1,1);f.db.update("update money_recommendation_runs set status='PREVIEW_REQUIRED'");counts(equivalent(filters()),1,1,1,0);}
 @ParameterizedTest @ValueSource(strings={"FAILED_KNOWN","STALE_CONFLICT","OUTCOME_UNKNOWN","QUEUED"}) void saveIssuesAreCountedOncePerEffectiveTransaction(String status){f.seed(1);UUID save=UUID.randomUUID();f.db.update("insert into money_recommendation_saves(id,user_id,request_id,request_hash) values(?,?,?,'synthetic')",save,f.f.owner,UUID.randomUUID());f.db.update("insert into money_recommendation_save_items(id,user_id,save_id,transaction_id,command,status) values(?,?,?,?,'{}',?)",UUID.randomUUID(),f.f.owner,save,f.transactions.getFirst(),status);f.db.update("update money_recommendation_items set status='FAILED_KNOWN'");counts(equivalent(filters()),1,1,1,1);}
 @ParameterizedTest @ValueSource(strings={"ACTIVE","COMPARISON_PENDING","REASSESSING","UNCLASSIFIABLE","FAILED_KNOWN","OUTCOME_UNKNOWN","SAVED","EXCLUDED"}) void readyMeansPersistedNonterminalDraftRatherThanSaveEligibility(String status){f.seed(1);f.db.update("update money_classification_drafts set status=?",status);counts(equivalent(filters()),1,1,Set.of("SAVED","EXCLUDED").contains(status)?0:1,0);}
 @ParameterizedTest @ValueSource(strings={"account","noAccounts","emptyAccounts","category","directCategory","uncategorized","parentCategory","origin","unknownOrigin","minMax","search","literalSearch"}) void filtersShareCurrentWorkbenchMembership(String scenario){
  f.seed(2);UUID first=f.transactions.getFirst();f.db.update("update money_transactions set category_id=? where id=?",f.f.category,first);f.db.update("insert into money_classification_state(user_id,transaction_id,origin,category_id) values(?,?,'AI',?)",f.f.owner,first,f.f.category);String account=null,category=null,origin=null,search="";BigDecimal min=null,max=null;long count=2;
  switch(scenario){case "account"->account=f.f.account.toString();case "noAccounts"->{account="none";count=0;}case "emptyAccounts"->{account="";count=0;}case "category"->{category=f.f.category.toString();count=1;}case "directCategory"->{category="direct:"+f.f.category;count=1;}case "uncategorized"->{category="uncategorized";count=1;}case "parentCategory"->{UUID parent=f.f.product.saveCategory(null,new MoneyProductService.CategoryInput("Parent","#123456",false,null,"EXPENSE",null,0)).id();UUID child=f.f.product.saveCategory(null,new MoneyProductService.CategoryInput("Child","#123456",false,null,"EXPENSE",null,0,parent,false)).id();f.db.update("update money_transactions set category_id=? where id=?",child,first);category=parent.toString();count=1;}case "origin"->{origin="AI,DIRECT";count=1;}case "unknownOrigin"->{origin="CONFIRMED";count=0;}case "minMax"->{override(first,Map.of("amount",new BigDecimal("1234.56")));min=new BigDecimal("1234");max=new BigDecimal("1235");count=1;}case "search"->{search="SYNTHETIC DRAFT 0";count=1;}case "literalSearch"->{search="%' OR 1=1 _";count=0;}}
  var r=equivalent(filter("EXPENSE",search,false,account,category,min,max,origin));assertThat(r.get("ALL")).isEqualTo(count);
 }
 @Test void foreignOwnerAccountsTransactionsDraftsAndIssuesNeverChangeCounts(){f.seed(1);UUID other=UUID.randomUUID(),account=UUID.randomUUID(),transaction=UUID.randomUUID();f.db.update("insert into qa_fixture_users values(?)",other);f.db.update("insert into money_accounts(id,user_id,provider,display_name,role) values(?,?,'IBK','Other','SPENDING')",account,other);f.db.update("insert into money_tracking_settings(user_id) values(?)",other);f.db.update("insert into money_tracking_accounts(user_id,kind,slot,account_id) values(?,'EXPENSE',1,?)",other,account);f.db.update("insert into money_transactions(id,user_id,type,from_account_id,amount,occurred_at,manual) values(?,?,'EXPENSE',?,1000,'2026-09-15T01:00:00Z',true)",transaction,other,account);f.db.update("insert into money_classification_drafts(id,user_id,transaction_id,status) values(?,?,?,'ACTIVE')",UUID.randomUUID(),other,transaction);counts(equivalent(filters()),1,1,1,0);counts(equivalent(filter("EXPENSE","",false,account.toString(),null,null,null,null)),0,0,0,0);}
 @Test void fractionalAmountFilterKeepsExistingValidation(){var p=filter("EXPENSE","",false,null,null,new BigDecimal("1234.56"),null,null);assertThatThrownBy(()->legacy(p)).hasMessage("Minimum must be a nonnegative KRW integer");assertThatThrownBy(()->f.service.summary(p)).hasMessage("Minimum must be a nonnegative KRW integer");}
 @Test void summaryReadCannotModifyFactsAccountsDecisionsDraftsSelectionsHistoryOrReasons(){f.seed(2);var tables=List.of("money_transactions","money_transaction_sources","money_accounts","money_bookkeeping_overrides","money_rule_projections","money_classification_state","money_classification_events","money_classification_drafts","money_classification_draft_revisions","money_classification_choices","money_recommendation_items","money_recommendation_runs","money_recommendation_saves","money_recommendation_save_items","money_review_decisions");var before=new LinkedHashMap<String,Object>();for(String t:tables)before.put(t,f.db.queryForList("select to_jsonb(t)::text as value from "+t+" t order by to_jsonb(t)::text"));equivalent(filters());for(String t:tables)assertThat(f.db.queryForList("select to_jsonb(t)::text as value from "+t+" t order by to_jsonb(t)::text")).isEqualTo(before.get(t));}
}
